import os
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, abort
import psycopg2
from psycopg2 import sql as psql

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')
HMAC_SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    return psycopg2.connect(host=DB_HOST, dbname=DB_NAME, user=DB_USER, password=DB_PASS)

def verify_request_signature(req):
    """Verify HMAC signature for internal service calls"""
    sig = req.headers.get('X-Request-Signature')
    ts = req.headers.get('X-Request-Timestamp')
    if not sig or not ts:
        return False
    # Replay protection: reject if older than 5 minutes
    try:
        if abs(time.time() - float(ts)) > 300:
            return False
    except (ValueError, TypeError):
        return False
    body = req.get_data(as_text=True)
    expected = hmac.new(HMAC_SECRET.encode(), f"{ts}:{body}".encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.route('/api/v1/reports/generate', methods=['POST'])
def generate_report():
    """Generate a filtered report based on user-specified criteria.
    Accepts JSON with: table, columns (list), filters (dict), group_by (optional)
    """
    data = request.get_json(force=True)

    # Validate required fields
    if not data or 'table' not in data or 'columns' not in data:
        return jsonify({"error": "Missing required fields"}), 400

    # Whitelist allowed tables
    allowed_tables = ['sales', 'inventory', 'shipments', 'returns']
    table = data['table']
    if table not in allowed_tables:
        return jsonify({"error": "Invalid table"}), 400

    # Whitelist allowed columns per table
    allowed_columns = {
        'sales': ['id', 'product_id', 'quantity', 'amount', 'region', 'sale_date'],
        'inventory': ['id', 'product_id', 'warehouse', 'quantity', 'last_updated'],
        'shipments': ['id', 'order_id', 'carrier', 'status', 'ship_date'],
        'returns': ['id', 'order_id', 'reason', 'status', 'return_date']
    }

    columns = data['columns']
    if not isinstance(columns, list) or not all(c in allowed_columns.get(table, []) for c in columns):
        return jsonify({"error": "Invalid columns"}), 400

    # Build query
    col_str = ', '.join(columns)
    query = f"SELECT {col_str} FROM {table}"

    # Apply filters - validated keys but VALUES are parameterized... mostly
    params = []
    if 'filters' in data and isinstance(data['filters'], dict):
        conditions = []
        for key, value in data['filters'].items():
            if key not in allowed_columns.get(table, []):
                return jsonify({"error": f"Invalid filter column: {key}"}), 400
            conditions.append(f"{key} = %s")
            params.append(value)
        if conditions:
            query += " WHERE " + " AND ".join(conditions)

    # Group by - THIS is where the vulnerability is
    if 'group_by' in data:
        group_col = data['group_by']
        # Developer assumed table/column whitelist above was sufficient
        # but group_by is not validated against the whitelist
        query += f" GROUP BY {group_col}"

    # Optional HAVING clause for aggregate filtering
    if 'having' in data:
        having_expr = data['having']
        query += f" HAVING {having_expr}"

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query, params)
        rows = cur.fetchall()
        cur.close()
        conn.close()
        return jsonify({"data": rows, "count": len(rows)})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({"error": "Query execution failed"}), 500

